package in.jharkhand.civic.controller;
import in.jharkhand.civic.service.ReferenceService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class ReferenceController {private final ReferenceService r;public ReferenceController(ReferenceService r){this.r=r;} @GetMapping("/departments") List<Map<String,Object>> deps(){return r.departments();}@GetMapping("/departments/{id}") Map<String,Object> dep(@PathVariable String id){return Optional.ofNullable(r.department(id)).orElseThrow();}@GetMapping("/institutions") List<Map<String,Object>> inst(@RequestParam(required=false) Integer tier,@RequestParam(required=false) String expertise){return r.institutions().stream().filter(x->tier==null||tier.equals(((Number)x.get("tier")).intValue())).filter(x->expertise==null||String.valueOf(x.get("expertise")).toLowerCase().contains(expertise.toLowerCase())).toList();}@GetMapping("/institutions/{id}") Map<String,Object> institution(@PathVariable String id){return Optional.ofNullable(r.institution(id)).orElseThrow();}}
